  public void AcquireDestination(){destinationGate=C.Gate(DestinationRoot,"registration.lock");}
  public void ReleaseDestination(){if(destinationGate!=null){destinationGate.Dispose();destinationGate=null;}}
  public void ReleaseBoth(){ReleaseDestination();if(sourceGate!=null){sourceGate.Dispose();sourceGate=null;}}
  void RequireGate(){C.Require(sourceGate!=null&&destinationGate!=null&&transactionGate!=null,"MUTATION_LOCK_REQUIRED");Fresh();}
  string At(string leaf){return Path.Combine(DestinationRoot,leaf);}
  public string PointerText(){return C.Canon(new Dictionary<string,object>{{"version",1},{"migrationId",Manifest["migrationId"]},{"manifestSHA256",ManifestHash},{"binding",DestinationBinding},{"descriptorRoot",DestinationRoot}});}
