  void SameProtected(string path,Dictionary<string,object> record,string code){C.Require(C.Canon(C.UnprotectFile(path))==C.Canon(record),code);}
  public bool HasPending(){if(!C.Exists(At("registration.bin")))return false;SameProtected(At("registration.bin"),Pending(),"DESTINATION_RECEIPT_CHANGED");return true;}
