  public void LoadJournal(){journal.Clear();string previous=new string('0',64);for(int i=0;i<Events.Length;i++){string p=At("migration-"+(i+1).ToString("D4")+".bin");if(!C.Exists(p)){for(int j=i+1;j<Events.Length;j++)C.Require(!C.Exists(At("migration-"+(j+1).ToString("D4")+".bin")),"JOURNAL_SEQUENCE_GAP");break;}var r=C.UnprotectFile(p);C.Fields(r,"version","migrationId","manifestSHA256","sequence","event","previousSHA256","details");C.Require(C.Num(r,"version",1,1)==1&&C.Str(r,"migrationId",36)==(string)Manifest["migrationId"]&&C.Str(r,"manifestSHA256",64)==ManifestHash&&C.Num(r,"sequence",1,Events.Length)==i+1&&C.Str(r,"event",32)==Events[i]&&C.Str(r,"previousSHA256",64)==previous,"JOURNAL_CHANGED");var detail=r["details"] as Dictionary<string,object>;C.Require(detail!=null,"JOURNAL_DETAILS_REJECTED");if(Events[i]=="probe-1"||Events[i]=="probe-2"){C.Fields(detail,"uid","bootId","ordinal","brokerPid","brokerCreated","brokerSHA256");C.Require(C.Num(detail,"uid",1,Int32.MaxValue)==Uid&&C.Num(detail,"ordinal",1,2)==(Events[i]=="probe-1"?1:2)&&C.Str(detail,"brokerSHA256",64)==(string)Destination["brokerSHA256"],"JOURNAL_PROBE_BINDING_CHANGED");C.Num(detail,"brokerPid",1,Int32.MaxValue);string created=C.Str(detail,"brokerCreated",32),boot=C.Str(detail,"bootId",36);long parsed;C.Require(Regex.IsMatch(created,"^[1-9][0-9]{0,18}$")&&Int64.TryParse(created,out parsed)&&parsed>0&&Regex.IsMatch(boot,"^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$")&&boot!="00000000-0000-0000-0000-000000000000","JOURNAL_PROBE_IDENTITY_REJECTED");if(Events[i]=="probe-2"){var first=Details("probe-1");C.Require((string)first["bootId"]==boot&&!((int)first["brokerPid"]==(int)detail["brokerPid"]&&(string)first["brokerCreated"]==created),"JOURNAL_PROBE_REUSED");}}else C.Fields(detail);journal.Add(r);previous=C.Binding(r);}}
