  public Dictionary<string,object> Migrate(string mode){PreAuthorize();C.Require(mode=="migrate"||mode=="resume","MODE_REJECTED");AcquireTransaction();bool prior=AnyIntent();if(mode=="migrate")C.Require(!prior,"MIGRATION_REPLAY_USE_RESUME");else C.Require(prior,"RESUME_INTENT_MISSING");
