    if(!Has("destination-stored")){
      C.Require(sourceExists&&PointerState()=="old"&&!C.Exists(Path.Combine(SourceRoot,"forgotten.bin")),"COPY_STATE_REJECTED");byte[] source=null;try{source=SourceSecret();if(!HubSshMaintenanceStore.Exists(DestinationTarget)){C.Require(!HasPending(),"DESTINATION_CREDENTIAL_MISSING");HubSshMaintenanceStore.Create(DestinationTarget,(string)Destination["user"],source,Comment);}else{byte[] dest=DestinationSecret();try{C.Require(HubSshMaintenanceStore.Equal(source,dest),"DESTINATION_CONTENT_CHANGED");}finally{Array.Clear(dest,0,dest.Length);}}}finally{if(source!=null)Array.Clear(source,0,source.Length);}Checkpoint("AFTER_CREDENTIAL_WRITE");
      if(!C.Exists(At("known_hosts")))C.CreateFile(At("known_hosts"),Encoding.ASCII.GetBytes(C.KnownHosts(Destination)));using(var kh=C.HoldFile(At("known_hosts"),1024))C.Require(C.Utf8.GetString(C.Read(kh))==C.KnownHosts(Destination),"DESTINATION_HOST_PIN_CHANGED");if(!HasPending())C.CreateFile(At("registration.bin"),C.Protected(C.Canon(Pending())));C.Require(HasPending(),"DESTINATION_RECEIPT_MISSING");Checkpoint("AFTER_PENDING_RECEIPT");AppendEmpty("destination-stored");C.Event("DESTINATION_STORED");
