    if(!C.Exists(At("activation.bin")))C.CreateFile(At("activation.bin"),C.Protected(C.Canon(Activation())));C.Require(Active(),"ACTIVATION_UNVERIFIED");Checkpoint("AFTER_ACTIVATION_RECEIPT");if(!Has("destination-active")){AppendEmpty("destination-active");C.Event("DESTINATION_ACTIVE");}
