  }
  void RecheckWithoutIntent(){RequireGate();C.Require((int)C.OldReceipt(Source,(string)Manifest["sourceReceiptSHA256"])["uid"]==Uid,"SOURCE_UID_CHANGED");}
  void VerifyCompleted(){C.Require(Active()&&!HubSshVaultStore.Exists(SourceTarget),"COMPLETION_STATE_CHANGED");VerifyActivationBackup();CheckSourceTomb();byte[] secret=DestinationSecret();Array.Clear(secret,0,secret.Length);}
  public Dictionary<string,object> Status(bool verifyCompleted=true){AcquireTransaction();AcquireBoth();bool any=AnyIntent();if(any){VerifyIntents(false);LoadJournal();}bool pending=HasPending(),active=pending&&Active();var r=C.Result(Has("completed")?"completed":active?"destination-active":pending?"pending-migration":any?"intent-recorded":"prepared");r["sourceExists"]=HubSshVaultStore.Exists(SourceTarget);r["destinationExists"]=HubSshMaintenanceStore.Exists(DestinationTarget);r["destinationPending"]=pending&&!active;r["destinationActive"]=active;r["pointerState"]=PointerState();r["sourceForgotten"]=C.Exists(Path.Combine(SourceRoot,"forgotten.bin"));if((bool)r["sourceForgotten"])CheckSourceTomb();r["expired"]=(int)Manifest["expiresAt"]<=Now();r["observedStateSHA256"]=ObservedStateHash();if(C.Exists(At("rollback.bin"))){if(verifyCompleted)VerifyRollback();r["state"]="rolled-back";r["destinationActive"]=false;r["destinationPending"]=false;}if(verifyCompleted&&Has("completed")){if(!active)r["state"]="recovery-required";else VerifyCompleted();}return r;}
#if HUB_SSH_MAINTENANCE_TEST
  public Dictionary<string,object> Fixture(bool cleanup){C.Require((string)Source["host"]=="127.0.0.1"&&(string)Source["user"]=="fixture"&&(string)Destination["host"]=="127.0.0.1"&&(string)Destination["user"]=="fixture","FIXTURE_TARGET_REJECTED");var r=Status(false);byte[] expected=C.Utf8.GetBytes(" Hub fixture 密碼 🔐 42 "),a=null,b=null;try{if((bool)r["sourceExists"]){a=SourceSecret();C.Require(HubSshMaintenanceStore.Equal(a,expected),"FIXTURE_CONTENT_REJECTED");}if((bool)r["destinationExists"]){b=DestinationSecret();C.Require(HubSshMaintenanceStore.Equal(b,expected),"FIXTURE_CONTENT_REJECTED");}r["bytesEqual"]=a!=null&&b!=null&&HubSshMaintenanceStore.Equal(a,b);if(cleanup){if(a!=null)HubSshVaultStore.Delete(SourceTarget);if(b!=null)HubSshMaintenanceStore.Delete(DestinationTarget,(string)Destination["user"],expected,Comment);return C.Result("fixture-cleaned");}return r;}finally{Array.Clear(expected,0,expected.Length);if(a!=null)Array.Clear(a,0,a.Length);if(b!=null)Array.Clear(b,0,b.Length);}}
#endif
  public void Dispose(){ReleaseBoth();if(transactionGate!=null){transactionGate.Dispose();transactionGate=null;}for(int i=held.Count-1;i>=0;i--)held[i].Dispose();held.Clear();}
